package com.quickcart.repository; import com.quickcart.entity.Product; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import java.util.*; public interface ProductRepository extends JpaRepository<Product,Long>{Page<Product> findByAvailableTrue(Pageable p); List<Product> findByCategoryIdAndAvailableTrue(Long id); @Query("select p from Product p where p.available=true and (lower(p.name) like lower(concat('%',:q,'%')) or lower(p.brand) like lower(concat('%',:q,'%')) or lower(p.category.name) like lower(concat('%',:q,'%')))") List<Product> search(String q);}